function selectionCards(){put('selectionCount',selected.size+' / 4');const host=$('selectedStations');host.replaceChildren();for(const k of selected){const s=stationMap.get(k);if(!s)continue;const card=document.createElement('article');card.className='research-station';card.style.setProperty('--station-color',colorFor(k));const title=document.createElement('strong');title.textContent=([...selected].indexOf(k)+1)+'. '+stationLabel(s);const p=document.createElement('p');p.textContent='Latest reported sample: '+(s.date||'unknown')+(Number.isFinite(sampleAge(s))&&sampleAge(s)>=0?' ('+sampleAge(s)+' days ago)':'')+' · '+s.count.toLocaleString()+' indexed results';const agency=document.createElement('p');agency.textContent='Reporting agency: '+(researchContacts[s.org]?.agency||s.org);const state=document.createElement('p');state.textContent=history.has(k)?'History ready · '+s.groups.size+' parameter combinations':pending.has(k)?'Retrieving history…':s.error?'History unavailable: '+s.error:'History not loaded';if(pending.has(k)&&!history.has(k)){state.classList.add('station-history-loading');const spinner=document.createElement('span');spinner.className='station-history-spinner';spinner.setAttribute('aria-hidden','true');state.prepend(spinner);}const b=document.createElement('button');b.type='button';b.textContent='Remove';b.onclick=()=>toggleStation(k);card.append(title,p,agency,state,b);const outreach=agencyOutreach(s);if(outreach)card.append(outreach);if(s.error){const retry=document.createElement('button');retry.type='button';retry.textContent='Retry history';retry.onclick=()=>{s.error='';ensureHistory(k).catch(()=>{});};card.append(retry)}host.append(card)}$('clearStations').disabled=!selected.size}
