function ingest(row){if(!Array.isArray(row)||row.length<23)return;const [org,rid,id,name,lat,lon,dt,ch,val,u,qual,depth,du,lab,accr,method,mdl,pql,matrix,wbid,modified,comment,fraction]=row;let d=date(dt),uid=norm(org)+'|'+norm(rid);if(!['21FLEECO','21FLCOFM'].includes(org)||!rid||!id||!ch||!d||seen.has(uid))return;seen.add(uid);const key=org+'|'+id;let s=stationMap.get(key);if(!s)return;let gkey=JSON.stringify([norm(ch),norm(u),norm(fraction),norm(matrix)]),g=s.groups.get(gkey);if(!g){g={name:norm(ch),unit:norm(u),fraction:norm(fraction),matrix:norm(matrix),records:[]};s.groups.set(gkey,g)}g.records.push({d,v:numeric(val),qual:norm(qual),comment:!!comment});names.add(lower(ch));}
async function json(url,signal){const response=await fetch(url,{signal,redirect:'follow',credentials:'omit'});if(!response.ok)throw Error('HTTP '+response.status);const content=await response.text();try{return JSON.parse(content)}catch(e){throw Error('Expected JSON but received a different response. Check public Apps Script deployment access.')}}
