function saveTrendCsv(){if(!trendData)return;const {series,rain,rainMode}=trendData;const rows=[['agency','station','analyte','unit','fraction','matrix','sample_date','value','qualifier','source_comment_present','KFMY_daily_rain_inches','selected_rainfall_window','selected_rainfall_inches']];for(const o of series)for(const p of o.rows){const v=rainMode==='off'?null:rainMode==='daily'?rain.get(p.d):total(p.d,+rainMode,rain);rows.push([o.s.org,o.s.id,o.g.name,o.g.unit,o.g.fraction,o.g.matrix,p.d,p.v,p.qual,p.comment,rain.get(p.d),rainMode,v])}download(new Blob([rows.map(r=>r.map(csvCell).join(',')).join('\n')],{type:'text/csv;charset=utf-8'}),'win-historical-trends.csv')}
function saveTrendPng(){if(!trendChart||!trendData)return;const src=$('trendChart'),out=document.createElement('canvas');out.width=src.width;out.height=src.height+85;const c=out.getContext('2d');c.fillStyle='#fff';c.fillRect(0,0,out.width,out.height);c.drawImage(src,0,0);c.fillStyle='#0b2d5b';c.font='13px system-ui';c.fillText(trendData.label+' | '+trendData.lo+' to '+trendData.hi,10,src.height+20,out.width-20);c.fillText('Florida DEP WIN · NOAA NCEI KFMY | amandazirzow.com',10,src.height+42,out.width-20);c.fillText('Accessed '+new Date().toLocaleDateString(),10,src.height+64,out.width-20);out.toBlob(b=>{if(b)download(b,'win-historical-trends.png')},'image/png')}

let seasonChart=null,seasonData=null;
function captionText(id,title,body){put(id+'Caption',title+' '+body+' Visualization: amandazirzow.com/water-research.html; accessed '+dayKey(Date.now())+'.'+(indexStamp?' WIN index generated '+indexStamp+'.':''));$(id+'Copy').disabled=false;put(id+'CopyStatus','')}
function clearCaption(id){put(id+'Caption','Generate the graph to create its figure description.');$(id+'Copy').disabled=true;put(id+'CopyStatus','')}
async function copyCaption(id){try{const el=$(id+'Caption');if(navigator.clipboard.write&&typeof ClipboardItem!=='undefined'){try{await navigator.clipboard.write([new ClipboardItem({'text/plain':new Blob([el.textContent],{type:'text/plain'}),'text/html':new Blob(['<p>'+el.innerHTML+'</p>'],{type:'text/html'})})])}catch(_){await navigator.clipboard.writeText(el.textContent)}}else await navigator.clipboard.writeText(el.textContent);put(id+'CopyStatus','Copied.')}catch(e){put(id+'CopyStatus','Clipboard unavailable; select and copy the caption text.')}}
function figurePng(canvasId,captionId,name){const src=$(canvasId),caption=$(captionId+'Caption').textContent,out=document.createElement('canvas');out.width=Math.max(640,src.width);const c=out.getContext('2d'),fontSize=Math.max(14,Math.round(out.width/95)),font=italic=>(italic?'italic ':'')+fontSize+'px system-ui';let lines=[],line=[],width=0;for(const part of scientificParts(caption)){for(const word of part.text.match(/\S+|\s+/g)||[]){c.font=font(part.italic);let w=c.measureText(word).width;if(width+w>out.width-36&&line.length&&word.trim()){lines.push(line);line=[];width=0}if(!line.length&&!word.trim())continue;line.push({text:word,italic:part.italic,width:w});width+=w}}if(line.length)lines.push(line);const height=src.height,step=Math.ceil(fontSize*1.5);out.height=height+lines.length*step+36;c.fillStyle='#fff';c.fillRect(0,0,out.width,out.height);c.drawImage(src,(out.width-src.width)/2,0);c.fillStyle='#142d45';lines.forEach((parts,i)=>{let x=18;for(const p of parts){c.font=font(p.italic);c.fillText(p.text,x,height+24+i*step);x+=p.width}});out.toBlob(b=>{if(b)download(b,name)},'image/png')}
function trendCaption(omitted){const {series,rain,lo,hi,label,rainMode}=trendData;const n=series.map(o=>{const plotted=o.days.filter(p=>$('trendScale').value!=='logarithmic'||p.y>0).length;return o.s.id+' ('+o.s.org+', n = '+plotted+' plotted days)'}).join('; ');let rainDescription='Rainfall not displayed.';if(rainMode!=='off'){let count=0;for(let t=Date.parse(lo);t<=Date.parse(hi);t+=DAY){const d=dayKey(t),v=rainMode==='daily'?rain.get(d):total(d,+rainMode,rain);if(v!=null)count++}rainDescription=count?(rainMode==='daily'?'Daily':'Preceding '+rainMode+'-day cumulative')+' precipitation (inches; right axis, blue bars) from NOAA NCEI Page Field (USW00012835); '+count+' complete plotted rainfall days/windows. Missing windows omitted.':'Rainfall requested but no complete rainfall observations currently plotted.'}
captionText('trend','Figure 1. '+label+' over time at selected WIN monitoring stations.','Date range: '+lo+' to '+hi+'. '+n+'. Left axis: '+$('trendScale').value+' scale. Points are daily arithmetic means of numeric, unqualified, uncommented measurements; lines connect sampled days only. Fraction: '+(series[0]?.g.fraction||'unspecified')+'; matrix: '+(series[0]?.g.matrix||'unspecified')+'. '+rainDescription+(omitted?' '+omitted+' nonpositive daily values omitted on log scale.':'')+' Water quality source: Florida DEP WIN. Rain gauge may not represent local rainfall; temporal association is not causation.')}
function regressionCaption(){if(!results.size||!context)return;const all=[...results.values()],dates=all.flatMap(o=>o.pairs.map(p=>p.d)).sort();captionText('reg','Figure 3. '+context.label+' versus '+context.w+'-day antecedent precipitation.','Paired sample dates: '+(dates.length?dates[0]+' to '+dates.at(-1):'no complete pairs')+'. '+all.map(o=>o.s.id+' ('+o.s.org+', n = '+o.pairs.length+' paired days'+(o.model?', training R² = '+fmt(o.model.r2):', no validated fit')+')').join('; ')+'. Fraction: '+(context.g.fraction||'unspecified')+'; matrix: '+(context.g.matrix||'unspecified')+'. '+(context.delta?'Response is change from the preceding eligible sampled day. ':'Response is the eligible daily mean. ')+' Circles show training or unfitted observations; triangles show chronological holdout observations. Lines are station-specific ordinary least-squares fits using earliest 75% of paired days where eligible, restricted to training rainfall ranges. Qualified, commented and nonnumeric results and incomplete rainfall windows are excluded. Sources: Florida DEP WIN and NOAA NCEI KFMY (USW00012835). Exploratory association, not a causal inference or forecast.')}
function quantile(vals,p){if(!vals.length)return null;const a=[...vals].sort((x,y)=>x-y),i=(a.length-1)*p,j=Math.floor(i);return a[j]+(a[Math.ceil(i)]-a[j])*(i-j)}
function resetSeason(){if(seasonChart){seasonChart.destroy();seasonChart=null}seasonData=null;$('seasonSave').disabled=$('seasonCsv').disabled=true;$('seasonRows').replaceChildren();clearCaption('season');put('seasonStatus','Select stations and a common parameter.')}
function showSeason(){resetSeason();const keys=[...selected],param=$('param').value,start=$('start').value,end=$('end').value;if(!keys.length||!param)return;if(start&&end&&start>end){put('seasonStatus','Start date must precede end date.');return}let groups=[],dates=[],label='',fraction='',matrix='';for(const k of keys){const s=stationMap.get(k),g=s?.groups.get(param);if(!g)continue;label=g.name+' ('+(g.unit||'unit unspecified')+')';fraction=g.fraction||'unspecified';matrix=g.matrix||'unspecified';let days=new Map();for(const p of g.records){if((start&&p.d<start)||(end&&p.d>end)||p.v===null||p.qual||p.comment)continue;let arr=days.get(p.d)||[];arr.push(p.v);days.set(p.d,arr)}const obs=[...days].sort((a,b)=>a[0].localeCompare(b[0])).map(([d,a])=>({d,y:mean(a)}));dates.push(...obs.map(p=>p.d));for(const wet of [false,true])groups.push({s,color:colorFor(k),season:wet?'Wet':'Dry',obs:obs.filter(p=>{const m=+p.d.slice(5,7);return (m>=6&&m<=9)===wet})})}if(!dates.length){put('seasonStatus','No eligible observations in this date range.');return}dates.sort();seasonData={groups,label,fraction,matrix,lo:start||dates[0],hi:end||dates.at(-1)};$('seasonCsv').disabled=false;drawSeason()}
function drawSeason(){if(!seasonData)return;const {groups,label,fraction,matrix,lo,hi}=seasonData,log=$('seasonScale').value==='logarithmic';let data=[],rows=[],omitted=0;const names=groups.map(o=>o.s.id+' · '+o.season);groups.forEach((o,i)=>{const vals=o.obs.filter(p=>{if(log&&p.y<=0){omitted++;return false}return true});const v=vals.map(p=>p.y),med=quantile(v,.5),q1=quantile(v,.25),q3=quantile(v,.75);rows.push({o,n:v.length,med,q1,q3});if(!v.length)return;const points=vals.map((p,j)=>({x:i+((j*0.61803398875)%1-.5)*.46,y:p.y,d:p.d}));data.push({type:'scatter',label:o.s.id+' '+o.season,data:points,backgroundColor:o.color+'65',pointRadius:2.5,order:2});data.push({type:'line',label:'IQR',data:[{x:i,y:q1},{x:i,y:q3}],borderColor:o.color,borderWidth:7,pointRadius:0,order:1});data.push({type:'scatter',label:'Median',data:[{x:i,y:med}],pointStyle:'rectRot',pointRadius:7,pointBackgroundColor:'#ffffff',pointBorderColor:o.color,pointBorderWidth:2,order:0})});if(seasonChart)seasonChart.destroy();if(typeof Chart!=='undefined'){seasonChart=new Chart($('seasonChart'),{type:'scatter',data:{datasets:data},options:{responsive:true,maintainAspectRatio:false,animation:false,scales:{x:{type:'linear',min:-.5,max:groups.length-.5,afterBuildTicks:s=>{s.ticks=groups.map((_,i)=>({value:i}))},ticks:{callback:v=>names[v]||'',autoSkip:false,maxRotation:45,minRotation:20},title:{display:true,text:'Monitoring station and season'}},y:{type:log?'logarithmic':'linear',title:{display:true,text:scientificOption(label)}}},plugins:{legend:{display:false},tooltip:{callbacks:{title:items=>names[Math.round(items[0]?.parsed.x)]||'',label:i=>i.raw.d?i.raw.d+': '+fmt(i.parsed.y):i.dataset.label+': '+fmt(i.parsed.y)}}}}});$('seasonSave').disabled=false}const frag=document.createDocumentFragment();for(const {o,n,med,q1,q3} of rows){const tr=document.createElement('tr');for(const v of [o.s.id+' ('+o.s.org+')',o.season,n,fmt(med),fmt(q1),fmt(q3)]){const td=document.createElement('td');td.textContent=v;tr.append(td)}frag.append(tr)}$('seasonRows').replaceChildren(frag);put('seasonStatus','Dots = daily means; thick bars = 25th–75th percentiles; diamonds = medians.'+(omitted?' '+omitted+' nonpositive daily values omitted on log scale; summaries use plotted days.':''));captionText('season','Figure 2. Seasonal distribution of '+label+' at selected WIN monitoring stations.','Date range: '+lo+' to '+hi+'. Wet season defined as June–September; dry season October–May (fixed calendar groups, not observed onset). '+rows.map(({o,n,med})=>o.s.id+' ('+o.s.org+') '+o.season+': n = '+n+' days, median '+fmt(med)).join('; ')+'. Fraction: '+fraction+'; matrix: '+matrix+'. Points show daily arithmetic means of numeric, unqualified, uncommented measurements; thick bars show 25th–75th percentiles and diamonds show medians; horizontal jitter separates points. '+$('seasonScale').value+' scale.'+(omitted?' '+omitted+' nonpositive daily values excluded from log plot and summaries.':'')+' Source: Florida DEP WIN. Seasons pooled across selected years; unequal sampling and other confounders may affect comparison. No significance test or causal inference.')}
function seasonCSV(){if(!seasonData)return;let rows=[['agency','station','season','date','analyte_unit','fraction','matrix','daily_mean']];for(const o of seasonData.groups)for(const p of o.obs)rows.push([o.s.org,o.s.id,o.season,p.d,seasonData.label,seasonData.fraction,seasonData.matrix,p.y]);download(new Blob([rows.map(r=>r.map(csvCell).join(',')).join('\n')],{type:'text/csv;charset=utf-8'}),'win-seasonal-comparison.csv')}

// Show real station-level progress at the parameter selector, not a simulated percentage.
const historyProgress=new Map();let parameterClock=null;
function parameterProgressUI(){
 const keys=[...selected],total=keys.length,ready=keys.filter(k=>history.has(k)).length,errors=keys.filter(k=>!history.has(k)&&stationMap.get(k)?.error),waiting=keys.filter(k=>!history.has(k)&&!stationMap.get(k)?.error);
 const active=waiting.length>0,select=$('param'),badge=$('parameterBadge'),panel=$('parameterLoading');
 const options=Math.max(0,select.options.length-1),state=!total?'idle':active?'loading':errors.length?'error':options?'ready':'empty';
 badge.dataset.state=state;select.disabled=state!=='ready';select.setAttribute('aria-busy',String(active));panel.hidden=!active&&!errors.length;
 put('parameterBadgeText',state==='loading'?ready+' / '+total+' ready':state==='ready'?options+' shared choices':state==='error'?'Retry needed':state==='empty'?'No shared choices':'Awaiting selection');
 const status=!total?'Select stations to retrieve their histories.':active?'Retrieving selected station histories. Shared parameters will appear automatically when every selected history is ready.':errors.length?'Some histories could not load. Use Retry history on the affected station card, or remove that station.':options?options+' compatible parameter combinations are available across '+total+' selected station(s).':'No exact common analyte, unit, fraction and matrix. Try a different station selection.';
 if($('parameterStatus').textContent!==status)put('parameterStatus',status);
 put('parameterLoadingTitle',active?'Loading station histories…':'Station history unavailable');
 const bar=$('parameterProgress');bar.max=Math.max(1,total);bar.value=ready;bar.setAttribute('aria-valuetext',ready+' of '+total+' station histories ready');
 const host=$('parameterStationProgress');host.replaceChildren();
 let began=Infinity;
 for(const k of keys){const s=stationMap.get(k);if(!s)continue;const p=historyProgress.get(k),row=document.createElement('div'),name=document.createElement('span'),detail=document.createElement('span');name.textContent=s.id+' ('+s.org+')';detail.textContent=history.has(k)?'Ready · '+s.groups.size+' combinations':s.error?'Failed · retry on card':p?.end!=null?p.offset.toLocaleString()+' / '+p.end.toLocaleString()+' rows':'Connecting · '+s.count.toLocaleString()+' indexed results';row.append(name,detail);host.append(row);if(!history.has(k)&&!s.error&&p)began=Math.min(began,p.started)}
 $('parameterElapsed').hidden=!active||!Number.isFinite(began);if(Number.isFinite(began))put('parameterElapsed',Math.floor((Date.now()-began)/1000)+' s elapsed');
 if(active&&!parameterClock)parameterClock=setInterval(parameterProgressUI,1000);
 if(!active&&parameterClock){clearInterval(parameterClock);parameterClock=null;}
}
